'use strict';
// Opt-in, nonvisual QA instrumentation; no cost in a normal game session.
window.frameMeter=location.search.includes('profile')?(()=>{const cpu=[],gaps=[];let last=0,publish=0,lastRenders=0;return{begin(now){if(last&&now-last<250)gaps.push(now-last);last=now;return performance.now();},end(start,now){cpu.push(performance.now()-start);if(cpu.length>180)cpu.shift();if(gaps.length>180)gaps.shift();if(now-publish<1000)return;const period=now-publish;publish=now;const percentile=a=>a.slice().sort((a,b)=>a-b)[Math.floor(a.length*.95)]||0;const d=document.documentElement.dataset,renders=window.potionFluid?.renderCount||0;d.gpuRendersPerSecond=((renders-lastRenders)*1000/period).toFixed(1);lastRenders=renders;d.cpuMax=Math.max(...cpu).toFixed(2);d.frameMax=Math.max(...gaps).toFixed(2);d.cpuMean=(cpu.reduce((a,b)=>a+b,0)/cpu.length).toFixed(2);d.cpuP95=percentile(cpu).toFixed(2);d.frameP95=percentile(gaps).toFixed(2);d.frameMean=(gaps.reduce((a,b)=>a+b,0)/Math.max(1,gaps.length)).toFixed(2);}};})():null;
